#!/usr/bin/env python3
"""Build departure boards from a timetable feed. Usage: boards.py INPUT_DIR OUTPUT_FILE"""
import csv
import json
import os
import sys
from datetime import date, datetime, timedelta
from zoneinfo import ZoneInfo


def read_csv(d, name):
    path = os.path.join(d, name)
    if not os.path.exists(path):
        return []
    with open(path, encoding="utf-8-sig", newline="") as f:
        rows = list(csv.reader(f))
    if not rows:
        return []
    header = [h.strip() for h in rows[0]]
    out = []
    for r in rows[1:]:
        if not r or all(not c.strip() for c in r):
            continue
        rec = {}
        for i, h in enumerate(header):
            rec[h] = r[i].strip() if i < len(r) else ""
        out.append(rec)
    return out


def to_int(v, default=0):
    v = (v or "").strip()
    return int(v) if v else default


def parse_time(s):
    h, m, sec = s.strip().split(":")
    return int(h) * 3600 + int(m) * 60 + int(sec)


def parse_date(s):
    s = s.strip()
    return date(int(s[0:4]), int(s[4:6]), int(s[6:8]))


def fmt(ts, tz):
    dt = datetime.fromtimestamp(ts, tz)
    off = dt.utcoffset()
    secs = int(off.total_seconds())
    sign = "+" if secs >= 0 else "-"
    secs = abs(secs)
    return dt.strftime("%Y-%m-%dT%H:%M:%S") + "%s%02d:%02d" % (sign, secs // 3600, secs % 3600 // 60)


def main(indir, outfile):
    agencies = read_csv(indir, "agency.txt")
    stops = {r["stop_id"]: r for r in read_csv(indir, "stops.txt")}
    routes = {r["route_id"]: r for r in read_csv(indir, "routes.txt")}
    trips = {r["trip_id"]: r for r in read_csv(indir, "trips.txt")}
    calendar = {r["service_id"]: r for r in read_csv(indir, "calendar.txt")}
    cdates = {}
    for r in read_csv(indir, "calendar_dates.txt"):
        cdates[(r["service_id"], parse_date(r["date"]))] = to_int(r["exception_type"])
    freqs = {}
    for r in read_csv(indir, "frequencies.txt"):
        freqs.setdefault(r["trip_id"], []).append(r)

    agency_tz = {}
    for a in agencies:
        agency_tz[a["agency_id"]] = a["agency_timezone"]
    first_agency = agencies[0]
    default_tz = first_agency["agency_timezone"]

    with open(os.path.join(indir, "request.json"), encoding="utf-8-sig") as f:
        req = json.load(f)
    dates = sorted(set(req["service_dates"]))

    # stop times per trip
    st = {}
    for r in read_csv(indir, "stop_times.txt"):
        st.setdefault(r["trip_id"], []).append(r)

    # prepare trips: list of stop entries (time, row) in order
    prepared = {}
    for tid, rows in st.items():
        if tid not in trips:
            continue
        rows.sort(key=lambda r: to_int(r["stop_sequence"]))
        n = len(rows)
        times = []
        for r in rows:
            t = r.get("departure_time") or r.get("arrival_time") or ""
            times.append(parse_time(t) if t else None)
        known = [i for i, t in enumerate(times) if t is not None]
        for a, b in zip(known, known[1:]):
            for i in range(a + 1, b):
                times[i] = times[a] + (times[b] - times[a]) * (i - a) // (b - a)
        prepared[tid] = (rows, times)

    def runs(service_id, d):
        ex = cdates.get((service_id, d))
        if ex == 1:
            return True
        if ex == 2:
            return False
        c = calendar.get(service_id)
        if not c:
            return False
        if not (parse_date(c["start_date"]) <= d <= parse_date(c["end_date"])):
            return False
        day = ["monday", "tuesday", "wednesday", "thursday", "friday", "saturday", "sunday"][d.weekday()]
        return c.get(day, "") == "1"

    def board_stop(stop_id):
        s = stops[stop_id]
        p = s.get("parent_station", "")
        if p and p in stops:
            return p
        return stop_id

    def tz_of(stop_id):
        z = stops[stop_id].get("stop_timezone", "")
        return z or default_tz

    tzcache = {}

    def zi(name):
        if name not in tzcache:
            tzcache[name] = ZoneInfo(name)
        return tzcache[name]

    # boards
    boards = {}
    for sid, s in stops.items():
        lt = to_int(s.get("location_type"))
        if lt == 1 or (lt == 0 and not s.get("parent_station", "")):
            boards[sid] = s

    result_deps = {}  # (stop, date) -> list of (key, dict)
    for sid in boards:
        for ds in dates:
            result_deps[(sid, ds)] = []

    for ds in dates:
        d = date.fromisoformat(ds)
        for tid, trip in trips.items():
            if tid not in prepared or not runs(trip["service_id"], d):
                continue
            route = routes[trip["route_id"]]
            ag = route.get("agency_id", "") or first_agency["agency_id"]
            atz = zi(agency_tz.get(ag, default_tz))
            noon = datetime(d.year, d.month, d.day, 12, 0, 0, tzinfo=atz)
            origin = int(noon.timestamp()) - 43200
            label = route.get("route_short_name") or route.get("route_long_name") or ""
            rows, times = prepared[tid]
            last = rows[-1]
            lastb = board_stop(last["stop_id"])
            fallback = stops[lastb]["stop_name"]
            trip_hs = trip.get("trip_headsign", "")
            fr = freqs.get(tid)
            base = times[0]
            for i, r in enumerate(rows[:-1]):
                if to_int(r.get("pickup_type")) == 1:
                    continue
                hs = r.get("stop_headsign") or trip_hs or fallback
                b = board_stop(r["stop_id"])
                if b not in boards:
                    continue
                btz = zi(tz_of(b))
                plat = stops[r["stop_id"]].get("platform_code") or None
                entries = []  # (feed_time, until_feed, headway, kind)
                if fr is None:
                    entries.append((times[i], None, None, "scheduled"))
                else:
                    off = times[i] - base
                    for w in fr:
                        s0 = parse_time(w["start_time"])
                        e0 = parse_time(w["end_time"])
                        h = to_int(w["headway_secs"])
                        if s0 >= e0 or h <= 0:
                            continue
                        k = (e0 - s0 - 1) // h
                        if to_int(w.get("exact_times")) == 1:
                            for j in range(k + 1):
                                entries.append((s0 + j * h + off, None, None, "scheduled"))
                        else:
                            entries.append((s0 + off, s0 + k * h + off, h, "interval"))
                for ft, un, hw, kind in entries:
                    inst = origin + ft
                    dep = {
                        "kind": kind,
                        "time": fmt(inst, btz),
                        "until": fmt(origin + un, btz) if un is not None else None,
                        "headway_secs": hw,
                        "route": label,
                        "headsign": hs,
                        "trip": tid,
                        "platform": plat,
                        "agency": ag,
                    }
                    key = (inst, label, hs, tid, plat is not None, plat or "")
                    result_deps[(b, ds)].append((key, dep))

    out_boards = []
    for sid in sorted(boards):
        for ds in dates:
            deps = result_deps[(sid, ds)]
            deps.sort(key=lambda x: x[0])
            out_boards.append({
                "stop_id": sid,
                "name": boards[sid]["stop_name"],
                "timezone": tz_of(sid),
                "service_date": ds,
                "departures": [x[1] for x in deps],
            })
    with open(outfile, "w", encoding="utf-8") as f:
        json.dump({"service_dates": dates, "boards": out_boards}, f, ensure_ascii=False)


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
